import type { Product } from "./types";

// Deterministic product guidance written as rules, not generated by the AI.
// The advisor will reuse exactly these rules, so the storefront and the AI
// can never disagree about what pairs with what.

export type CareAdvice = {
  pairWith: string; // product handle
  avoid?: string; // product handle
  reason: string;
};

export function careAdvice(p: Product): CareAdvice | null {
  if (p.brand === "Afterglow Essentials") return null;
  // Only devices get lubricant guidance (not gift boxes, cards or accessories).
  const isDevice =
    p.tags.includes("rechargeable") || p.tags.includes("body-safe-silicone") || /stroker|sleeve/i.test(p.type);
  if (!isDevice) return null;
  if (p.tags.includes("body-safe-silicone")) {
    return {
      pairWith: "silk-glide",
      avoid: "velvet-silicone",
      reason:
        "Silicone-based lubricants are generally not recommended with silicone products, so a water-based formula is the safe pairing.",
    };
  }
  return {
    pairWith: "silk-glide",
    reason: "A water-based lubricant is compatible with every material in this collection.",
  };
}

